package com.finsightai.service;
import com.finsightai.model.*;import com.finsightai.repository.*;import org.springframework.boot.CommandLineRunner;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;import java.math.BigDecimal;import java.time.LocalDate;
@Component public class DataSeeder implements CommandLineRunner {private final TransactionRepository tx;private final AppUserRepository users;private final PasswordEncoder encoder;public DataSeeder(TransactionRepository t,AppUserRepository u,PasswordEncoder e){tx=t;users=u;encoder=e;}public void run(String...a){if(!users.existsByUsername("admin")){AppUser u=new AppUser();u.setUsername("admin");u.setPassword(encoder.encode("Admin@123"));u.setRole("ADMIN");users.save(u);}if(!users.existsByUsername("analyst")){AppUser u=new AppUser();u.setUsername("analyst");u.setPassword(encoder.encode("Analyst@123"));u.setRole("FINANCE_ANALYST");users.save(u);}if(tx.count()>0)return;String[]cats={"Software","Cloud","Payroll","Marketing","Sales","Operations"};for(int i=0;i<96;i++){Transaction t=new Transaction();t.setTransactionDate(LocalDate.now().minusDays(i*2));t.setCategory(cats[i%cats.length]);t.setAccount(i%2==0?"Operating":"Corporate");t.setType(i%4==0?"INCOME":"EXPENSE");double amount=i%4==0?42000+(i%7)*1800:6500+(i%11)*700;if(i==17)amount=125000;if(i==58)amount=98000;t.setAmount(BigDecimal.valueOf(amount));t.setDepartment(i%3==0?"Engineering":i%3==1?"Finance":"Sales");t.setSourceSystem(i%3==0?"SAP":i%3==1?"Oracle":"Dynamics");t.setDescription("ERP imported transaction #"+(10000+i));tx.save(t);}}}
